@namespace sv_933b48c587df491fb2c53377dca2e33d.Components.Pages.Settings
@using sv_933b48c587df491fb2c53377dca2e33d.Services
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="container-fluid py-4">
    <div class="row">
        <div class="col-md-3 col-lg-2">
            <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="section => _activeSection = section" />
        </div>
        <div class="col-md-9 col-lg-10">
            @if (_loading)
            {
                <div class="d-flex justify-content-center py-5">
                    <div class="spinner-border" role="status">
                        <span class="visually-hidden">Loading...</span>
                    </div>
                </div>
            }
            else
            {
                @switch (_activeSection)
                {
                    case "Profile":
                        <ProfileSection Profile="_profile" OnSave="SaveProfileAsync" />
                        break;
                    case "Notifications":
                        <NotificationsSection Prefs="_notificationPrefs" AllChannels="_allChannels" OnSave="SaveNotificationsAsync" />
                        break;
                    case "Security":
                        <SecuritySection TwoFactorEnabled="_securitySettings?.TwoFactorEnabled ?? false"
                                         LastPasswordChange="_securitySettings?.LastPasswordChange"
                                         Sessions="_securitySettings?.Sessions ?? new()"
                                         CurrentSessionId="@_currentSessionId"
                                         OnChangePassword="ChangePasswordAsync"
                                         OnTwoFactorToggle="ToggleTwoFactorAsync"
                                         OnRevoke="RevokeSessionAsync" />
                        break;
                    case "Appearance":
                        <AppearanceSection Settings="_appearanceSettings" OnSave="SaveAppearanceAsync" />
                        break;
                }
            }
        </div>
    </div>
</div>

@code {
    private string _activeSection = "Profile";
    private bool _loading = true;

    private UserProfile? _profile;
    private NotificationPrefs? _notificationPrefs;
    private SecuritySettings? _securitySettings;
    private AppearanceSettings? _appearanceSettings;
    private string? _currentSessionId;

    // Available channels for muting
    private List<string> _allChannels = new() { "general", "announcements", "random", "engineering", "design", "marketing" };

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettingsAsync();
        _loading = false;
    }

    private async Task LoadAllSettingsAsync()
    {
        _profile = await SettingsService.GetProfileAsync();
        _notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _appearanceSettings = await SettingsService.GetAppearanceAsync();

        // Assume first session is current
        if (_securitySettings?.Sessions.Count > 0)
        {
            _currentSessionId = _securitySettings.Sessions[0].Id;
        }
    }

    private async Task SaveProfileAsync(UserProfile profile)
    {
        await SettingsService.SaveProfileAsync(profile);
        _profile = profile;
    }

    private async Task SaveNotificationsAsync(NotificationPrefs prefs)
    {
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _notificationPrefs = prefs;
    }

    private async Task ChangePasswordAsync((string Current, string New) passwords)
    {
        await SettingsService.ChangePasswordAsync(passwords.Current, passwords.New);
    }

    private Task ToggleTwoFactorAsync(bool enabled)
    {
        // In a real app, this would call a service method
        if (_securitySettings is not null)
        {
            _securitySettings = _securitySettings with { TwoFactorEnabled = enabled };
        }
        return Task.CompletedTask;
    }

    private async Task RevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        if (_securitySettings is not null)
        {
            var updatedSessions = _securitySettings.Sessions.Where(s => s.Id != sessionId).ToList();
            _securitySettings = _securitySettings with { Sessions = updatedSessions };
        }
    }

    private async Task SaveAppearanceAsync(AppearanceSettings settings)
    {
        await SettingsService.SaveAppearanceAsync(settings);
        _appearanceSettings = settings;
    }
}

