{"path": "/tmp/sv-933b48c587df491fb2c53377dca2e33d/Components/Pages/Settings/AppearanceSection.razor", "file_text": "@namespace sv_933b48c587df491fb2c53377dca2e33d.Components.Pages.Settings
@using sv_933b48c587df491fb2c53377dca2e33d.Services

<div class="appearance-section">
    <h4 class="mb-4">Appearance Settings</h4>

    @if (_successMessage is not null)
    {
        <div class="alert alert-success alert-dismissible fade show" role="alert">
            @_successMessage
            <button type="button" class="btn-close" @onclick="() => _successMessage = null"></button>
        </div>
    }

    <div class="row">
        <div class="col-md-6">
            <div class="card mb-4">
                <div class="card-body">
                    <h6 class="card-title">Theme</h6>
                    @foreach (var theme in _themes)
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
                                   value="@theme" checked="@(_theme == theme)"
                                   @onchange="() => _theme = theme" />
                            <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                        </div>
                    }
                </div>
            </div>

            <div class="card mb-4">
                <div class="card-body">
                    <h6 class="card-title">Font Size</h6>
                    @foreach (var size in _fontSizes)
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{size}")"
                                   value="@size" checked="@(_fontSize == size)"
                                   @onchange="() => _fontSize = size" />
                            <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                        </div>
                    }
                </div>
            </div>

            <div class="card mb-4">
                <div class="card-body">
                    <h6 class="card-title">Language</h6>
                    <select class="form-select" @bind="_language">
                        @foreach (var lang in _languages)
                        {
                            <option value="@lang">@lang</option>
                        }
                    </select>
                </div>
            </div>

            <div class="card mb-4">
                <div class="card-body">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                        <label class="form-check-label" for="compactMode">Compact Mode</label>
                    </div>
                </div>
            </div>

            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                @if (_saving)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Save
            </button>
        </div>

        <div class="col-md-6">
            <AppearancePreview Theme="@_theme" FontSize="@_fontSize" CompactMode="@_compactMode" />
        </div>
    </div>
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private static readonly string[] _themes = { "Light", "Dark", "System" };
    private static readonly string[] _fontSizes = { "Small", "Medium", "Large" };
    private static readonly string[] _languages = { "English", "Spanish", "French", "German", "Japanese", "Chinese" };

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private bool _saving;
    private string? _successMessage;

    protected override void OnParametersSet()
    {
        if (Settings is not null && !_saving)
        {
            _theme = Settings.Theme;
            _fontSize = Settings.FontSize;
            _language = Settings.Language;
            _compactMode = Settings.CompactMode;
        }
    }

    private async Task SaveAsync()
    {
        _saving = true;
        var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await OnSave.InvokeAsync(updated);
        _saving = false;
        _successMessage = "Appearance settings saved!";
    }
}
"}

{"path": "/tmp/sv-933b48c587df491fb2c53377dca2e33d/Components/Pages/Settings/SettingsPage.razor", "file_text": "@page "/settings"
@namespace sv_933b48c587df491fb2c53377dca2e33d.Components.Pages.Settings
@using sv_933b48c587df491fb2c53377dca2e33d.Services
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="container-fluid py-4">
    <div class="row">
        <div class="col-md-3 col-lg-2">
            <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="section => _activeSection = section" />
        </div>
        <div class="col-md-9 col-lg-10">
            @if (_loading)
            {
                <div class="d-flex justify-content-center py-5">
                    <div class="spinner-border" role="status">
                        <span class="visually-hidden">Loading...</span>
                    </div>
                </div>
            }
            else
            {
                @switch (_activeSection)
                {
                    case "Profile":
                        <ProfileSection Profile="_profile" OnSave="SaveProfileAsync" />
                        break;
                    case "Notifications":
                        <NotificationsSection Prefs="_notificationPrefs" AllChannels="_allChannels" OnSave="SaveNotificationsAsync" />
                        break;
                    case "Security":
                        <SecuritySection TwoFactorEnabled="_securitySettings?.TwoFactorEnabled ?? false"
                                         LastPasswordChange="_securitySettings?.LastPasswordChange"
                                         Sessions="_securitySettings?.Sessions ?? new()"
                                         CurrentSessionId="@_currentSessionId"
                                         OnChangePassword="ChangePasswordAsync"
                                         OnTwoFactorToggle="ToggleTwoFactorAsync"
                                         OnRevoke="RevokeSessionAsync" />
                        break;
                    case "Appearance":
                        <AppearanceSection Settings="_appearanceSettings" OnSave="SaveAppearanceAsync" />
                        break;
                }
            }
        </div>
    </div>
</div>

@code {
    private string _activeSection = "Profile";
    private bool _loading = true;

    private UserProfile? _profile;
    private NotificationPrefs? _notificationPrefs;
    private SecuritySettings? _securitySettings;
    private AppearanceSettings? _appearanceSettings;
    private string? _currentSessionId;

    // Available channels for muting
    private List<string> _allChannels = new() { "general", "announcements", "random", "engineering", "design", "marketing" };

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettingsAsync();
        _loading = false;
    }

    private async Task LoadAllSettingsAsync()
    {
        _profile = await SettingsService.GetProfileAsync();
        _notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _appearanceSettings = await SettingsService.GetAppearanceAsync();

        // Assume first session is current
        if (_securitySettings?.Sessions.Count > 0)
        {
            _currentSessionId = _securitySettings.Sessions[0].Id;
        }
    }

    private async Task SaveProfileAsync(UserProfile profile)
    {
        await SettingsService.SaveProfileAsync(profile);
        _profile = profile;
    }

    private async Task SaveNotificationsAsync(NotificationPrefs prefs)
    {
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _notificationPrefs = prefs;
    }

    private async Task ChangePasswordAsync((string Current, string New) passwords)
    {
        await SettingsService.ChangePasswordAsync(passwords.Current, passwords.New);
    }

    private Task ToggleTwoFactorAsync(bool enabled)
    {
        // In a real app, this would call a service method
        if (_securitySettings is not null)
        {
            _securitySettings = _securitySettings with { TwoFactorEnabled = enabled };
        }
        return Task.CompletedTask;
    }

    private async Task RevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        if (_securitySettings is not null)
        {
            var updatedSessions = _securitySettings.Sessions.Where(s => s.Id != sessionId).ToList();
            _securitySettings = _securitySettings with { Sessions = updatedSessions };
        }
    }

    private async Task SaveAppearanceAsync(AppearanceSettings settings)
    {
        await SettingsService.SaveAppearanceAsync(settings);
        _appearanceSettings = settings;
    }
}
"}

